await page.locator('#tasks-nav').click();await page.locator('[data-challenge=\"0\"]').click();await page.locator('#editor').fill('powtorz 4 [np 100 pw 90]');await page.locator('#check-challenge').click();assert.match(await page.locator('#challenge-result').textContent(),/Udało/);
await page.locator('#editor').fill('np 10\\nnp 2 / 0');await page.locator('#speed').fill('100');await page.locator('#run').click();await page.waitForFunction(()=>"'!document.querySelector('"'#error').hidden);assert.match(await page.locator('#error').textContent(),/Wiersz 2, kol. 4/);assert.equal(await page.locator('.inline-error').count(),1);
await page.locator('#editor').fill('powtorz 20 [np 1 pw 18]');await page.locator('#step').click();await page.locator('#step').click();assert.equal(await page.locator('#segment-count').textContent(),'1 odcinków');assert.ok(await page.locator('.executing').count()>0);
await page.reload();assert.equal(await page.locator('#editor').inputValue(),'powtorz 20 [np 1 pw 18]');
await page.locator('#theme').click();await page.locator('#theme').click();await page.screenshot({path:'/tmp/logomocja-dark.png',fullPage:true});
await page.setViewportSize({width:390,height:844});await page.evaluate(()=>window.logomocja.open('powtorz 12 [powtorz 4 [np 100 pw 90] pw 30]','2d'));await page.screenshot({path:'/tmp/logomocja-mobile.png',fullPage:true});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
await page.locator('#reference-nav').click();assert.equal(await page.locator('table tbody tr').count(),21);await page.locator('#modal-close').click();
const noGL=await browser.newContext();await noGL.addInitScript(()=>{const old=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(type,...a){if(type.includes('webgl'))return null;return old.call(this,type,...a)}});const off=await noGL.newPage();await off.goto(base);await off.waitForFunction(()=>window.logomocja);await off.locator('#mode-3d').click();assert.match(await off.locator('#view-name').textContent(),/WEBGL/);await off.locator('#mode-2d').click();assert.match(await off.locator('#view-name').textContent(),/2D/);
assert.deepEqual(errors,[]);assert.deepEqual(network,[]);await browser.close();console.log('Browser checks passed: 13 examples, 3D, files, drafts, sharing, challenge, errors, stepping, themes, mobile, reference, WebGL fallback.');
